 $data=[
 'linux.php'=>['Linux essentials','Get comfortable where DevOps starts: the command line.','SYSTEMS / MODULE 01','A good first move is learning to navigate, inspect and change files with confidence.','Linux',[['NAVIGATION','Move around the filesystem','Print your location, list files, and move into a project directory.','pwd && ls -la && cd ~/projects'],['FILES','Create a project folder','Create a directory tree and an empty file in one step.','mkdir -p demo/logs && touch demo/README.md'],['INSPECT','Read a file safely','Print a file, then search its contents for a word.','cat README.md\ngrep -n "setup" README.md'],['PERMISSIONS','Understand executable files','Inspect permissions and grant execute permission to a script you own.','ls -l deploy.sh\nchmod u+x deploy.sh'],['PROCESSES','Find a running process','Filter the process list to locate a service by name.','ps aux | grep nginx'],['PIPELINES','Combine commands','Count matching log lines without creating an intermediate file.','grep -i "error" app.log | wc -l']]],
 'docker.php'=>['Docker fundamentals','Build, run and inspect containers with practical commands.','CONTAINERS / MODULE 03','Containers package an app and its runtime dependencies so it behaves consistently across machines.','Docker',[['FIRST RUN','Run a container','Download and run a tiny test image, then clean it up automatically.','docker run --rm hello-world'],['LIFECYCLE','Start a web server','Run nginx in the background and publish its port locally.','docker run -d --name web -p 8080:80 nginx'],['INSPECT','See what is running','List containers and read the last lines of the container log.','docker ps\ndocker logs --tail 20 web'],['BUILD','Build your own image','Build the Dockerfile in the current directory and give it a tag.','docker build -t hello-app:dev .'],['NETWORK','Connect with Compose','Start the services described in your compose file.','docker compose up -d'],['CLEANUP','Stop a container','Stop and remove a named container when you finish experimenting.','docker stop web && docker rm web']]],
 'terraform.php'=>['Terraform foundations','Learn the plan-and-apply workflow behind infrastructure as code.','INFRASTRUCTURE AS CODE / MODULE 04','Terraform describes desired infrastructure in configuration. Practice the workflow locally first; cloud providers may create billable resources.','Terraform',[['INSTALL','Check your CLI','Confirm the installed Terraform CLI version.','terraform version'],['INIT','Initialize a project','Install providers and initialize the working directory.','terraform init'],['FORMAT','Format configuration','Apply the standard Terraform formatting to your files.','terraform fmt -recursive'],['VALIDATE','Check your config','Validate syntax and internal consistency after initialization.','terraform validate'],['PLAN','Preview changes','Review planned actions before applying any infrastructure changes.','terraform plan'],['STATE','Inspect state','List resources recorded in the state file. Protect state files as sensitive data.','terraform state list']]],
 'aws.php'=>['AWS cloud essentials','Understand the building blocks behind a well-designed cloud environment.','CLOUD / MODULE 02','These guided tasks explain core AWS services. They are learning exercises: review costs and permissions before using a real account.','AWS',[['EC2','Launch a virtual server','EC2 provides resizable compute. A secure launch starts with a trusted image, restricted security group and key pair.','Concept: AMI → instance type → security group → key pair'],['S3','Store an object','S3 stores objects in buckets. Keep public access blocked and grant the smallest required access.','Concept: bucket → object key → IAM policy'],['IAM','Grant least privilege','Use roles and narrowly scoped policies. Avoid sharing root credentials or embedding access keys.','Concept: principal → action → resource → condition'],['VPC','Plan a network','A VPC is a logically isolated network. Separate public and private subnets by purpose.','Concept: VPC → subnets → route tables → security groups'],['RDS','Use a managed database','RDS manages database operations. Keep databases private and restrict inbound access to app services.','Concept: engine → subnet group → parameter group'],['SAFE PRACTICE','Practice without surprises','Start with diagrams and local simulations. Before real cloud work, review region, pricing, permissions and cleanup.','Checklist: estimate cost · scope access · verify region · clean up']]]
 ]; [$title,$sub,$label,$intro,$tag,$lessons]=$data[$path]; headerView($path); ?><section class="page-hero wrap"><div class="breadcrumb"><a href="index.php">Home</a><span>/</span><a href="roadmap.php">Learning paths</a><span>/</span><b><?= $tag ?></b></div><div class="eyebrow"><?= $label ?></div><h1><?= $title ?></h1><p class="hero-lead"><?= htmlspecialchars($sub) ?></p></section><section class="wrap lesson-layout"><aside class="lesson-aside"><div class="aside-card"><span class="aside-label">IN THIS MODULE</span><h3><?= count($lessons) ?> practical lessons</h3><div class="module-progress"><span data-progress-label>0 / <?= count($lessons) ?> complete</span><div class="progress-track"><i data-progress-bar></i></div></div><p><?= htmlspecialchars($intro) ?></p><a class="text-link" href="roadmap.php">← Back to roadmap</a></div><div class="terminal-tip"><span>PRO TIP</span><p>Try each task yourself before checking the command. Experimenting is part of learning.</p></div></aside><div class="lesson-grid"><?php lessonCards($lessons,strtolower($tag)); ?></div></section><?php footerView(); exit;
