if($path==='roadmap.php'){ headerView($path); ?><section class="page-hero wrap"><div class="eyebrow">YOUR LEARNING PATH</div><h1>A roadmap with<br><span class="gradient-text">real momentum.</span></h1><p class="hero-lead">A practical sequence from your first terminal command to understanding how production systems fit together.</p></section><section class="wrap roadmap-list"><?php $steps=[['01','Linux & the command line','Build your foundation: files, permissions, processes, networking and shell basics.','linux.php','4–6 hours'],['02','Cloud concepts & AWS','Understand identity, networking, compute, storage and managed databases.','aws.php','5–7 hours'],['03','Containers with Docker','Package an app, work with images, and connect services using Compose.','docker.php','4–6 hours'],['04','Infrastructure as code','Read and validate Terraform configuration; understand plans and state.','terraform.php','4–6 hours'],['05','Git, CI/CD & observability','Round out your toolkit with version control, delivery pipelines, logs and metrics.','interview.php','Continue exploring']]; foreach($steps as $s): ?><article class="roadmap-row"><div class="roadmap-index"><?= $s[0] ?></div><div class="roadmap-body"><div class="lesson-meta"><span class="tag">LEARNING STAGE <?= $s[0] ?></span><span class="duration"><?= $s[4] ?></span></div><h2><?= $s[1] ?></h2><p><?= $s[2] ?></p><a class="text-link" href="<?= $s[3] ?>">Explore this stage <span>→</span></a></div><span class="roadmap-mark">↗</span></article><?php endforeach; ?></section><section class="wrap callout"><div><span class="eyebrow">KEEP YOUR MOMENTUM</span><h2>Progress is built one task at a time.</h2></div><a class="button primary" href="progress.php">View my progress →</a></section><?php footerView(); exit; }
if($path==='about.php'){ headerView($path); ?><section class="page-hero wrap"><div class="eyebrow">WHY THIS HUB EXISTS</div><h1>DevOps feels big.<br><span class="gradient-text">Your next step doesn't.</span></h1><p class="hero-lead">DevOps Learning Hub turns a broad field into small, practical lessons you can follow at your own pace.</p></section><section class="wrap about-grid"><article class="about-panel"><span class="about-number">01</span><h2>Learn the fundamentals</h2><p>Start with Linux and core concepts, then move into cloud, containers and infrastructure as code.</p></article><article class="about-panel"><span class="about-number">02</span><h2>Practice as you go</h2><p>Each module includes approachable tasks and commands that help you build confidence through repetition.</p></article><article class="about-panel"><span class="about-number">03</span><h2>Keep your own pace</h2><p>There are no deadlines or prerequisites. Track completed lessons in this browser and return when ready.</p></article></section><?php footerView(); exit; }
if($path==='interview.php'){ $qa=[['What is DevOps?','A set of practices and a culture that bring development and operations closer together. Teams use automation and feedback to deliver changes reliably.'],['What is a Linux process?','A running instance of a program. The operating system assigns it a process ID (PID), resources and a lifecycle.'],['What is a container?','A process isolated using operating-system features and packaged with its application dependencies. Containers share the host kernel.'],['What is a Docker image?','A read-only template used to create containers. Images are built in layers and can be versioned and shared through registries.'],['What does Terraform plan do?','It compares the declared configuration with known state and provider data, then previews proposed changes without applying them.'],['What is least privilege?','Granting a user, role or service only the permissions it needs, for only the resources and time it needs them.'],['What is a VPC?','A logically isolated virtual network in AWS where you define address ranges, subnets, routes and traffic controls.'],['How do you troubleshoot an unavailable service?','Check scope and recent changes, confirm DNS and connectivity, inspect health and logs, then test dependencies and roll back or mitigate carefully.']]; headerView($path); ?><section class="page-hero wrap"><div class="eyebrow">PRACTICE YOUR EXPLANATIONS</div><h1>Interview prep,<br><span class="gradient-text">without the guesswork.</span></h1><p class="hero-lead">Use these questions to practice clear, concise explanations of core DevOps concepts.</p></section><section class="wrap qa-list"><?php foreach($qa as $i=>$item): ?><details class="qa-item"><summary><span class="qa-number"><?= str_pad((string)($i+1),2,'0',STR_PAD_LEFT) ?></span><span><?= htmlspecialchars($item[0]) ?></span><b>+</b></summary><p><?= htmlspecialchars($item[1]) ?></p></details><?php endforeach; ?></section><?php footerView(); exit; }
